            { name: 'Affix', code: '<div data-spy="affix" data-offset-top="60">...</div>', description: 'Sticky positioning (removed in v4)', preview: '<div style="background: #fcf8e3; padding: 0.75rem; border-radius: 4px; border: 1px solid #faebcc;"><p style="margin: 0; font-size: 0.8rem; color: #8a6d3b;"><strong>Affix:</strong> Makes element sticky when scrolling past offset. Removed in Bootstrap 4 (use CSS position: sticky).</p></div>' }
